// The NestJS backend kit: a server made with NestJS. It recognises one by
// its packages, runs it with its own start script on the port it is given,
// and makes a new one with the Nest command line's own starter.
import { basename } from "node:path";
import { defineKit } from "@software-factory/core";
import { commandsOf, doesOf, readableName, readPackageJson, verifyCommand, } from "./package-json.js";
const PORT = 3000;
export const nestjsBackend = defineKit({
    id: "nestjs-backend",
    name: "NestJS backend",
    about: "A server made with NestJS.",
    kind: "nestjs-backend",
    commands: { start: "npm start" },
    rules: [
        "rules/nestjs-backend/conventions.md",
        "rules/nestjs-backend/lessons.md",
    ],
    port: PORT,
    detect: (folder) => {
        const file = readPackageJson(folder);
        if (!file?.packages.has("@nestjs/core"))
            return null;
        return {
            name: readableName(file, folder),
            commands: commandsOf({
                start: file.scripts.has("start:dev")
                    ? "npm run start:dev"
                    : "npm start",
                verify: verifyCommand(file),
            }),
        };
    },
    partsFor: (product) => {
        const port = product.port ?? PORT;
        return [
            {
                id: product.id,
                name: product.name,
                area: "products",
                does: doesOf(product, "server"),
                dependsOn: product.dependsOn,
                folder: product.folder,
                prepare: [{ label: "Installing packages", packages: true }],
                // Without a health address, the port being open counts as started.
                run: startScript(product),
                env: { PORT: String(port) },
                port: { fixed: port },
                start: "auto",
            },
        ];
    },
    create: (folder) => [
        [
            "npx",
            "@nestjs/cli@latest",
            "new",
            basename(folder),
            "--package-manager",
            "npm",
            "--skip-git",
        ],
    ],
});
// The product's start command as a program to run: "npm run start:dev" or
// "npm start".
function startScript(product) {
    return product.commands.start === "npm run start:dev"
        ? ["npm", "run", "start:dev"]
        : ["npm", "start"];
}
